import{_ as l,o,c as t,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"CDS Hammer (Day 2) - Quota Discussion","description":"","frontmatter":{"title":"CDS Hammer (Day 2) - Quota Discussion","date":"2014-10-30T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["Ceph","分布式存储","CFS配额","子树配额","子卷"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_2_-_Quota_Discussion.md","filePath":"posts/2014/CDS_Hammer_Day_2_-_Quota_Discussion.md","lastUpdated":1780459816000}'),n={name:"posts/2014/CDS_Hammer_Day_2_-_Quota_Discussion.md"};function a(s,i,r,p,u,g){return o(),t("div",null,[...i[0]||(i[0]=[e("<p><strong>会议纪要</strong></p><p><strong>会议主题</strong>： 讨论Ceph分布式存储系统中CFS配额支持的实现以及配额与子树的关系</p><p><strong>会议时间</strong>： 2023年11月（具体日期未知）</p><p><strong>参会人员</strong>： Sage, Yanchon, Josh, John Craig, Lee（通过聊天室）</p><p><strong>会议内容</strong>：</p><p><strong>1. 配额支持讨论</strong></p><ul><li>Sage介绍了CFS配额支持的实现方案，包括如何在目录创建时集成文件parents，并查找所有配额信息和状态。</li><li>指出配额实现可能不够精确，需要进一步改进。</li><li>讨论了在创建操作频繁发生时配额可能被超限的问题。</li></ul><p><strong>2. 子树配额跟踪</strong></p><ul><li>Sage提到当前子树配额跟踪存在一些问题，例如在文件重命名时配额信息不会更新，导致配额无法正确执行。</li><li>提出使用“subtree”概念来跟踪文件属于哪个配额，确保检查正确的配额。</li></ul><p><strong>3. 配额与子卷</strong></p><ul><li>Josh建议将配额与子卷结合，以便在目录上设置配额并创建快照。</li><li>讨论了使用现有的“snap realm”数据结构来跟踪inode成员资格，并使用“sub volume”概念来限制操作。</li></ul><p><strong>4. 测试和改进</strong></p><ul><li>Sage建议添加测试用例来验证配额功能，并确保它能够在达到配额限制时阻止写入操作。</li><li>讨论了对配额实现进行改进的建议，例如处理截断操作和优化统计信息传播。</li></ul><p><strong>5. 决策</strong></p><ul><li>会议决定将配额与子卷结合，并使用现有的“snap realm”数据结构来跟踪inode成员资格。</li><li>决定添加测试用例来验证配额功能，并对配额实现进行改进。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Sage将添加测试用例来验证配额功能。</li><li>Sage将对配额实现进行改进，例如处理截断操作和优化统计信息传播。</li><li>John Craig将研究使用更严格的目录结构来限制配额的方法。</li></ul><p><strong>关键词</strong>：</p><ul><li>CFS配额</li><li>subtree</li><li>sub volume</li><li>snap realm</li><li>inode</li><li>MTS</li><li>quota enforcement</li><li>truncate operation</li><li>Ceph</li><li>分布式存储</li><li>CRUSH algorithm</li><li>high availability</li><li>scalability</li><li>object storage</li><li>block storage</li><li>file system storage</li><li>consistency</li><li>decentralization</li><li>performance</li><li>bluestore</li><li>bluefs</li><li>rocksdb</li><li>OSD</li><li>MON</li><li>MDS</li><li>PG</li><li>RADOS</li><li>librados</li><li>libcephfs</li><li>cephfs</li><li>rbd</li><li>radosgw</li><li>RGW</li><li>RESTful API</li><li>authentication</li><li>authorization</li><li>encryption</li><li>erasure coding</li><li>replication</li><li>snapshots</li><li>clones</li><li>thin provisioning</li><li>iSCSI</li><li>Fibre Channel</li><li>NFS</li><li>CIFS</li><li>POSIX</li><li>monitoring</li><li>dashboard</li><li>management</li><li>orchestration</li><li>automation</li><li>integration</li><li>containerization</li><li>Kubernetes</li><li>Docker</li><li>virtualization</li><li>cloud computing</li><li>AWS</li><li>Azure</li><li>Google Cloud</li><li>hybrid cloud</li><li>multi-cloud</li><li>storage cluster</li><li>node</li><li>disk</li><li>SSD</li><li>HDD</li><li>JBOD</li><li>SAN</li><li>NAS</li><li>network</li><li>topology</li><li>failure domain</li><li>recovery</li><li>resilience</li><li>load balancing</li><li>caching</li><li>compression</li><li>deduplication</li><li>tiering</li><li>performance tuning</li><li>benchmarking</li><li>testing</li><li>validation</li></ul>",19)])])}const d=l(n,[["render",a]]);export{_ as __pageData,d as default};
